        if isinstance(x, bool):
            return d
        if isinstance(x, int):
            return x
        if isinstance(x, float):
            return int(x)
        if isinstance(x, str):
            s = x.strip()
            if s and (s.lstrip("-").isdigit()):
                return int(s)
        return d

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return iv(v[0]), iv(v[1])
        if isinstance(v, dict):
            for k in ("position", "pos", "loc", "location", "coordinates", "coord"):
                if k in v:
                    return pos(v[k])
        return 0, 0

    def items(v):
        return v if isinstance(v, list) else ([] if v is None else [v])

    w = iv(g.get("grid_width", g.get("width", 0)))
    h = iv(g.get("grid_height", g.get("height", 0)))

    sx, sy = pos(g.get("self_position", g.get("self", g.get("agent", (0, 0)))))
    ox, oy = pos(g.get("opponent_position", g.get("opponent", g.get("enemy", (0, 0)))))

    obs = set()
    for k in ("obstacles", "walls", "blocked", "occupied"):
        for v in items(g.get(k, [])):
            obs.add(pos(v.get("position", v)) if isinstance(v, dict) else pos(v))

    pts = []
    for k in ("resources", "targets", "control_points", "points", "goals", "territories", "cells"):
        for v in items(g.get(k, [])):
            pts.append(pos(v.get("position", v)) if isinstance(v, dict) else pos(v))

    if not pts:
        pts = [(ox, oy)]

    # Prefer targets that are close to us but not too close to opponent.
    tx, ty = pts[0]
    best = None
    for x, y in pts:
        ds = abs(x - sx) + abs(y - sy)
        do = abs(x - ox) + abs(y - oy)
        score = ds * 2 - do
        if best is None or score < best[0] or (score == best[0] and ds < best[1]):
            best = (score, ds, x, y)
    tx, ty = best[2], best[3]

