    away = abs(sx - ox) + abs(sy - oy) <= 2

    cands = [(0, 0)]
    if abs(tx - sx) >= abs(ty - sy):
        cands += [(1, 0), (-1, 0), (0, 1), (0, -1)]
    else:
        cands += [(0, 1), (0, -1), (1, 0), (-1, 0)]
    cands += [(1, 1), (1, -1), (-1, 1), (-1, -1)]

    best_move = [0, 0]
    best_score = None

    for dx, dy in cands:
