        if (w and (nx < 0 or nx >= w)) or (h and (ny < 0 or ny >= h)):
            continue
        if (nx, ny) in obs:
            continue

        d_target = abs(tx - nx) + abs(ty - ny)
        d_opp = abs(nx - ox) + abs(ny - oy)

        # Gentle exploration / territory preference: move toward open space if no clear target.
        open_bonus = 0
        for ax, ay in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            if ((nx + ax, ny + ay) not in obs) and (not w or 0 <= nx + ax < w) and (not h or 0 <= ny + ay < h):
                open_bonus += 1

        score = d_target * 4 - d_opp * (3 if away else 1) - open_bonus

        if away:
            score -= (abs(nx - ox) + abs(ny - oy)) * 2

        if best_score is None or score < best_score or (score == best_score and (dx, dy) < tuple(best_move)):
            best_score = score
            best_move = [dx, dy]

    return best_move

